import type { StreamingPlatformId } from '@/lib/streamingPlatforms'
import { cn } from '@/lib/utils'

const props = withDefaults(
  defineProps<{
    platform: StreamingPlatformId | string
    variant?: 'full' | 'icon'
    class?: string
  }>(),
  {
    variant: 'full',
  },
)

const normalizedPlatform = computed(() => {
  const p = props.platform?.toLowerCase()
  if (p === 'disney' || p === 'disneyplus') return 'disney'
  if (p === 'prime' || p === 'amazon' || p === 'primevideo') return 'prime'
  if (p === 'apple' || p === 'appletv') return 'apple'
  return 'netflix'
})
